from collections import Counter
import itertools

def get_prime_factors(n):
    factors = Counter()
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return factors

def find_solutions_v2(max_k, max_a):
    solutions = {1}
    for k in range(1, max_k + 1):
        # combinations_with_replacement(range(1, max_a + 1), k)
        # is good for k=4, max_a=20.
        # For k=4, max_a=20, it's combinations(20+4-1, 4) = combinations(23, 4) = 8855.
        # For k=5, max_a=20, it's combinations(24, 5) = 42504.
        for a_tuple in itertools.combinations_with_replacement(range(1, max_a + 1), k):
            v = 1
            for a in a_tuple:
                v *= (12 * a + 1)

            factors = get_prime_factors(v)
            if len(factors) == k:
                f_exps = sorted(factors.values())
                if f_exps == sorted(a_tuple):
                    solutions.add(v)
    return solutions

print(find_solutions_v2(5, 20))

